select
id, company_code, company_name, company_location, industry, scale, status, create_time, update_time
from company


        and id = #{id}


        and company_code = #{companyCode}


        and company_name = #{companyName}


        and company_location = #{companyLocation}


        and industry = #{industry}


        and scale = #{scale}


        and status = #{status}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from company


        and id = #{id}


        and company_code = #{companyCode}


        and company_name = #{companyName}


        and company_location = #{companyLocation}


        and industry = #{industry}


        and scale = #{scale}


        and status = #{status}


        and create_time = #{createTime}


        and update_time = #{updateTime}
